window.hockeyCalendarActivate=function(uid){const entry=(s.settings.calendarGames||[]).find(x=>x.uid===uid);if(!entry)return false;if(s.games.length)return alert('Finish or archive the current game day before switching schedules.');s.daySchedule=JSON.parse(JSON.stringify(entry));s.goalies=gameIndexes().map(i=>s.goalies[i]??null);s.mode=gameIndexes().map(i=>s.mode[i]||'mixed');save();render();return true};
function gameFormatPanel(g){return '<div class="row"><label>Skaters on ice <select onchange="setGameSkaters('+g+',this.value)">'+Array.from({length:10},(_,i)=>i+1).map(n=>'<option value="'+n+'" '+(gameSkaters(g)===n?'selected':'')+'>'+n+' skaters</option>').join('')+'</select></label><span class="muted">'+gamePresent(g).length+' available including goalie</span></div><details><summary>Game '+(g+1)+' attendance / late arrivals</summary><div class="row">'+s.players.map(x=>'<label class="pill"><input type="checkbox" '+(gamePresent(g).includes(x.id)?'checked':'')+' onchange="toggleGameAttendance('+g+','+x.id+',this.checked)"> '+e(label(x.id))+'</label>').join('')+'</div></details>'}
function dayView(){const schedule=activeGameSchedule();return calendarGameDay()+'<section class="card"><h2>'+e(gameDayHeading())+'</h2><p>'+present().length+' players attending</p><p class="muted">'+dayGameCount()+' games · '+s.settings.gameMinutes+' minutes each · '+s.settings.shiftMinutes+'-minute shifts · '+s.settings.skaters+' default skaters + goalie</p>'+gameIndexes().map(g=>'<section class="card"><strong>'+e(gameOpponentLabel(g))+'</strong>'+gameScheduleLabel(schedule,g)+gameFormatPanel(g)+'<div class="row"><label>Rotation <select onchange="s.mode['+g+']=this.value;save();render()"><option value="mixed" '+(s.mode[g]==='mixed'?'selected':'')+'>Mix teammates</option><option value="fixed" '+(s.mode[g]==='fixed'?'selected':'')+'>Keep groups</option></select></label><label>Goalie <select onchange="s.goalies['+g+']=this.value?+this.value:null;save();render()"><option value="">Auto</option>'+present().map(id=>'<option value="'+id+'" '+(s.goalies[g]===id?'selected':'')+'>'+e(label(id))+'</option>').join('')+'</select></label></div><p>Assigned: <b>'+e(s.games[g]?label(s.games[g].goalie):'Not generated')+'</b></p></section>').join('')+'<div class="row"><button class="primary" onclick="if(!s.games.length||confirm(\'Regenerate all shifts and overwrite manual edits?\'))generate()">Generate rotations</button><button onclick="nextDay()">Finish game day</button></div><p class="muted">Settings changes apply when you regenerate. Existing generated shifts stay unchanged until then.</p></section>'}
function rosterView(){return '<section class="card"><h2>Roster and attendance</h2><p class="muted">Attendance shown for '+e(gameOpponentLabel(s.game))+'. Game-specific changes do not alter other games.</p>'+s.players.map((x,i)=>'<div class="row"><input aria-label="Attending this game" type="checkbox" '+(gamePresent(s.game).includes(x.id)?'checked':'')+' onchange="toggleGameAttendance(s.game,'+x.id+',this.checked)"><input class="name" aria-label="Name" value="'+e(x.name)+'" onchange="s.players['+i+'].name=this.value;save()"><input class="num" aria-label="Jersey" value="'+e(x.number)+'" onchange="s.players['+i+'].number=this.value;save()"><button onclick="if(confirm(\'Remove player?\')){s.players.splice('+i+',1);save();render()}">Remove</button></div>').join('')+'<button onclick="s.players.push({id:Math.max(0,...s.players.map(p=>p.id))+1,name:\'New player\',number:\'\',present:true});save();render()">Add player</button></section>'}function shiftView(){return s.games.length?s.games.map((gm,g)=>'<section class="card"><h2>'+e(gameOpponentLabel(g))+' · Goalie '+e(label(gm.goalie))+'</h2>'+(gameScheduleMeta(g)?'<p class="muted">'+e(gameScheduleMeta(g))+'</p>':'')+'<div class="scroll"><table><tr><th>Time</th><th>Skaters</th><th></th></tr>'+gm.shifts.map((ids,i)=>'<tr><td>'+(i*s.settings.shiftMinutes)+'–'+Math.min(s.settings.gameMinutes,(i+1)*s.settings.shiftMinutes)+'</td><td>'+ids.map(id=>e(label(id))).join(', ')+'</td><td><button onclick="editShift('+g+','+i+')">Edit</button></td></tr>').join('')+'</table></div><h3>Skater minutes</h3>'+present().filter(id=>id!==gm.goalie).map(id=>'<span class="pill">'+e(label(id))+': '+gm.shifts.filter(a=>a.includes(id)).length*s.settings.shiftMinutes+' min</span>').join('')+'</section>').join(''):'<section class="card">Generate rotations on the Game day tab first.</section>'}const BENCH_PRESETS={'6U':['timed',false,false],'8U':['timed',false,false],'10U':['timed',true,false],'12U':['manual',true,true],'14U':['manual',true,true],'16U':['manual',true,true],'18U':['manual',true,true],'Custom':['timed',false,false]};
function benchConfig(){let z=s.settings,d=BENCH_PRESETS[z.division]||BENCH_PRESETS.Custom;return {mode:z.benchMode||d[0],stats:z.benchStats===null?d[1]:!!z.benchStats,ice:z.benchIce===null?d[2]:!!z.benchIce,gameClock:z.benchGameClock!==false,shiftClock:z.benchShiftClock!==false}}
function benchChange(k,v){if(k==='benchMode'){if(!['timed','manual','off'].includes(v))return;stop()}else if(k==='benchStats'||k==='benchIce'||k==='benchGameClock'||k==='benchShiftClock')v=!!v;else return;s.settings[k]=v;save();render()}
function benchReset(){if(!confirm('Restore Live Bench division defaults?'))return;Object.assign(s.settings,{benchMode:null,benchStats:null,benchIce:null,benchGameClock:true,benchShiftClock:true});save();render()}
function benchSettings(){let c=benchConfig();return '<h3>Live Bench</h3><label>Shift mode <select onchange="benchChange(&quot;benchMode&quot;,this.value)">'+[['timed','Timed rotations'],['manual','Manual lines'],['off','Off']].map(([v,n])=>'<option value="'+v+'" '+(c.mode===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><div class="row"><label><input type="checkbox" '+(c.stats?'checked':'')+' onchange="benchChange(&quot;benchStats&quot;,this.checked)"> Statistics</label><label><input type="checkbox" '+(c.ice?'checked':'')+' onchange="benchChange(&quot;benchIce&quot;,this.checked)"> Ice time</label></div><div class="row"><label><input type="checkbox" '+(c.gameClock?'checked':'')+' onchange="benchChange(&quot;benchGameClock&quot;,this.checked)"> Show game clock</label><label><input type="checkbox" '+(c.shiftClock?'checked':'')+' onchange="benchChange(&quot;benchShiftClock&quot;,this.checked)"> Show shift clock</label></div><p class="muted">Hidden clocks keep running. Timer controls remain available. The shift clock appears in Timed rotations mode.</p><button onclick="benchReset()">Restore division defaults</button><p class="muted">Disabled features are hidden, not deleted.</p>'}
function gameClock(){let k=s.day+'-'+s.game;return s.gameClocks[k]||(s.gameClocks[k]={period:1,duration:periodMinutes()*60,elapsed:0,since:null,ended:false})}
function clockElapsed(c){return Math.floor(c.elapsed+(c.since?(Date.now()-c.since)/1000:0))}
function clockText(c){let n=c.duration-clockElapsed(c);return n>=0?fmt(n):'+'+fmt(-n)}
function clockToggle(){let c=gameClock();if(c.ended)return;if(c.since){c.elapsed=clockElapsed(c);c.since=null}else c.since=Date.now();save();render()}
function clockEnd(){let c=gameClock();if(!confirm('End period '+c.period+'?'))return;c.elapsed=clockElapsed(c);c.since=null;c.ended=true;c.endedAt=Date.now();let lr=lineupRecord();lr.boundaries=lr.boundaries||[];lr.boundaries.push({type:'end',wall:c.endedAt,period:c.period});stop();save();render()}
function clockNext(){let c=gameClock();if(!c.ended||c.period>=s.settings.periodCount)return;let lr=lineupRecord();lr.boundaries=lr.boundaries||[];lr.boundaries.push({type:'start',wall:Date.now(),period:c.period+1});Object.assign(c,{period:c.period+1,duration:periodMinutes()*60,elapsed:0,since:null,ended:false,endedAt:null});save();render()}
function lineupRecord(){let k=s.day+'-'+s.game;return s.lineupRecords[k]||(s.lineupRecords[k]={current:null,events:[],pending:false})}
function lineupStamp(){let c=gameClock();return {wall:Date.now(),period:c.period,elapsed:clockElapsed(c)}}
function confirmLineup(ids,reason){let gm=s.games[s.game],eligible=gamePresent(s.game).filter(id=>id!==gm.goalie);if(ids.length!==gameSkaters(s.game)||new Set(ids).size!==ids.length||ids.some(id=>!eligible.includes(id)))return alert('Choose unique present skaters, within the on-ice limit.');let r=lineupRecord(),before=r.current||[],stamp=lineupStamp();r.current=ids.slice();r.pending=false;r.events.push({id:'lineup-'+stamp.wall+'-'+r.events.length,before:before.slice(),after:ids.slice(),reason,stamp});save();render()}
function confirmPlannedLineup(){confirmNextLineup()}
let subOpen=false,subOut=null,subIn=null;
function substitutePlayers(){subOpen=!subOpen;subOut=null;subIn=null;render()}
function chooseOut(id){subOut=id;subIn=null;render()}
function chooseIn(id){subIn=id;render()}
function commitSub(){let gm=s.games[s.game],r=lineupRecord(),current=r.current||gm.shifts[s.shift]||[],bench=gamePresent(s.game).filter(id=>id!==gm.goalie&&!current.includes(id));if(!current.includes(subOut)||!bench.includes(subIn))return alert('Choose an on-ice player and an eligible bench player.');let updated=current.map(id=>id===subOut?subIn:id);subOpen=false;subOut=null;subIn=null;confirmLineup(updated,'substitution')}
function substitutionPanel(){if(!subOpen)return '';let gm=s.games[s.game],r=lineupRecord(),current=r.current||gm.shifts[s.shift]||[],bench=gamePresent(s.game).filter(id=>id!==gm.goalie&&!current.includes(id));return '<div class="card"><h3>Quick substitution</h3><p>Coming off</p><div class="row">'+current.map(id=>'<button class="'+(subOut===id?'primary':'')+'" onclick="chooseOut('+id+')">'+e(label(id))+'</button>').join('')+'</div><p>Going on · eligible bench</p><div class="row">'+(bench.length?bench.map(id=>'<button class="'+(subIn===id?'primary':'')+'" onclick="chooseIn('+id+')">'+e(label(id))+'</button>').join(''):'No eligible skaters')+'</div><button class="primary" '+(subOut===null||subIn===null?'disabled':'')+' onclick="commitSub()">Confirm substitution</button> <button onclick="substitutePlayers()">Cancel</button></div>'}

function keepCurrentLineup(){let r=lineupRecord();r.pending=false;s.seconds=shiftSeconds();save();render()}
function nextPlannedLine(){stop();let gm=s.games[s.game];if(s.shift>=gm.shifts.length-1)return alert('Last planned shift.');s.shift++;s.seconds=shiftSeconds();lineupRecord().pending=true;save();render()}
function lineupTotals(){let r=lineupRecord(),ev=r.events,totals={},c=gameClock(),now=Date.now(),end=c.ended?c.endedAt||now:now,breaks=[],open=null;for(let mark of r.boundaries||[]){if(mark.type==='end')open=mark.wall;else if(mark.type==='start'&&open!==null){breaks.push([open,mark.wall]);open=null}}if(open!==null)breaks.push([open,now]);for(let i=0;i<ev.length;i++){let from=ev[i].stamp.wall,to=Math.min(ev[i+1]?.stamp.wall??end,end);if(to<=from)continue;let seconds=(to-from)/1000;for(let [x,y] of breaks)seconds-=Math.max(0,Math.min(to,y)-Math.max(from,x))/1000;seconds=Math.max(0,seconds);for(let id of ev[i].after)totals[id]=(totals[id]||0)+seconds}return totals}
function statsRecord(){let k=s.day+'-'+s.game;return s.statEvents[k]||(s.statEvents[k]=[])}
function recordStat(type,side){
 if(window.HockeyCloud.team&&!window.HockeyCloud.canEdit('games'))return alert('Game editing permission required.');
 const c=gameClock();if(c.ended)return alert('Start the next period before recording more events.');
 if(side==='us'){pendingStat={type,side,day:s.day,game:s.game,playerId:null,stage:'player'};render();return}
 commitStat(type,side,null);
}
function commitStat(type,side,playerId,extra={}){
 const c=gameClock();if(c.ended)return alert('Start the next period before recording more events.');
 statsRecord().push({id:'stat-'+Date.now()+'-'+statsRecord().length,type,side,playerId,...extra,period:c.period,elapsed:clockElapsed(c),wall:Date.now()});
 pendingStat=null;save();render();
}
function chooseStatPlayer(id){
 if(!pendingStat)return;
 const selection=pendingStat;
 if(selection.day!==s.day||selection.game!==s.game){pendingStat=null;render();return}
 if(id!==null&&!gamePresent(s.game).includes(id))return alert('Select an available player.');
 if(selection.type==='save'&&id!==null&&id!==s.games[s.game].goalie)return alert('Select the assigned goalie.');
 if(selection.type!=='save'&&id===s.games[s.game].goalie)return alert('Select a skater.');
 if(selection.type==='goal'){selection.playerId=id;selection.stage='primary';render();return}
 commitStat(selection.type,selection.side,id);
}
function chooseAssist(id){
 if(!pendingStat||pendingStat.type!=='goal')return;
 const ids=gamePresent(s.game).filter(x=>x!==s.games[s.game].goalie&&x!==pendingStat.playerId);
 if(id!==null&&!ids.includes(id))return alert('Select an eligible teammate.');
 if(pendingStat.stage==='primary'){pendingStat.primaryAssist=id;pendingStat.stage='secondary';render();return}
 if(id!==null&&id===pendingStat.primaryAssist)return alert('Choose a different teammate.');
 commitStat('goal','us',pendingStat.playerId,{primaryAssist:pendingStat.primaryAssist??null,secondaryAssist:id});
}
function cancelStatPlayer(){pendingStat=null;render()}
function statPlayerPicker(){
 if(!pendingStat||pendingStat.day!==s.day||pendingStat.game!==s.game)return '';
 const pick=pendingStat,goalie=s.games[s.game].goalie;
 const ids=gamePresent(s.game).filter(id=>pick.stage==='player'?(pick.type==='save'?id===goalie:id!==goalie):(id!==goalie&&id!==pick.playerId&&id!==pick.primaryAssist));
 const action=pick.stage==='player'?'chooseStatPlayer':'chooseAssist';
 const title=pick.stage==='primary'?'Primary assist':pick.stage==='secondary'?'Secondary assist':'Select player for '+pick.type;
 return '<section class="stat-picker"><h4>'+e(title)+'</h4><div class="stat-player-grid">'+ids.map(id=>'<button type="button" onclick="'+action+'('+id+')">'+e(label(id))+'</button>').join('')+'</div><div class="row"><button onclick="'+action+'(null)">None / unknown</button><button onclick="cancelStatPlayer()">Cancel</button></div></section>';
}
function undoStat(){if(window.HockeyCloud.team&&!window.HockeyCloud.canEdit('games'))return;let ev=statsRecord();if(!ev.length)return;if(!confirm('Undo the most recent game event?'))return;ev.pop();save();render()}
function deleteStat(id){if(window.HockeyCloud.team&&!window.HockeyCloud.canEdit('games'))return; if(!confirm('Delete this recorded event?'))return;s.statEvents[s.day+'-'+s.game]=statsRecord().filter(x=>x.id!==id);save();render()}
function editStat(id){
 if(window.HockeyCloud.team&&!window.HockeyCloud.canEdit('games'))return;
 const event=statsRecord().find(x=>x.id===id);if(!event)return;
 const type=prompt('Event type: goal, shot, save, penalty',event.type);if(type===null)return;
 if(!['goal','shot','save','penalty'].includes(type.toLowerCase().trim()))return alert('Unknown event type.');
 const roster=event.side==='us'?s.players.map(x=>x.number).join(', '):'opponent';
 const number=prompt('Player jersey number (blank for unknown). Available: '+roster,event.playerId?p(event.playerId)?.number||'':'');if(number===null)return;
 const player=number.trim()?s.players.find(x=>String(x.number)===number.trim()):null;
 if(number.trim()&&!player)return alert('Jersey number not found.');
 const primary=type==='goal'&&event.side==='us'?prompt('Primary assist jersey (blank for none)',event.primaryAssist?p(event.primaryAssist)?.number||'':''):'';
 if(primary===null)return;
 const secondary=type==='goal'&&event.side==='us'?prompt('Secondary assist jersey (blank for none)',event.secondaryAssist?p(event.secondaryAssist)?.number||'':''):'';
 if(secondary===null)return;
 const findAssist=n=>n.trim()?s.players.find(x=>String(x.number)===n.trim())?.id:null;
 if((primary.trim()&&!findAssist(primary))||(secondary.trim()&&!findAssist(secondary)))return alert('Assist jersey not found.');
 const ids=[player?.id,findAssist(primary),findAssist(secondary)].filter(x=>x!==null&&x!==undefined);
 if(new Set(ids).size!==ids.length)return alert('Scorer and assists must be different players.');
 Object.assign(event,{type:type.toLowerCase().trim(),playerId:player?.id??null,primaryAssist:findAssist(primary),secondaryAssist:findAssist(secondary)});
 save();render();
}
function statsSummary(events){
 const counts={};for(const ev of events){if(ev.side!=='us')continue;
 const add=(id,k)=>{if(id==null)return;const row=counts[id]||(counts[id]={goal:0,assist:0,shot:0,save:0,penalty:0});row[k]++};
 add(ev.playerId,ev.type);if(ev.type==='goal'){add(ev.playerId,'shot');add(ev.primaryAssist,'assist');add(ev.secondaryAssist,'assist')}
 }return counts;
}
function statsPanel(){
 const events=statsRecord(),count=(side,type)=>events.filter(ev=>ev.side===side&&(ev.type===type||(type==='shot'&&ev.type==='goal'))).length;
 const controls=side=>'<div class="stat-actions">'+[['goal','Goal'],['shot','Shot'],['save','Goalie save'],['penalty','Penalty']].map(([type,label])=>'<button type="button" onclick="recordStat(&quot;'+type+'&quot;,&quot;'+side+'&quot;)">'+label+'</button>').join('')+'</div>';
 const summary=statsSummary(events);
 return '<h3>Game statistics</h3><p><strong>Us '+count('us','goal')+' – '+count('them','goal')+' Opponent</strong> · Shots '+(count('us','shot')+count('them','save'))+'–'+(count('them','shot')+count('us','save'))+'</p><div class="stat-columns"><section class="stat-team"><h4>Our team</h4>'+controls('us')+'</section><section class="stat-team"><h4>Opponent</h4>'+controls('them')+'</section></div>'+statPlayerPicker()+
 '<details><summary>Player statistics</summary><div class="scroll"><table><tr><th>Player</th><th>G</th><th>A</th><th>Shots</th><th>Saves</th><th>PIM events</th></tr>'+Object.entries(summary).map(([id,v])=>'<tr><td>'+e(label(+id))+'</td>'+['goal','assist','shot','save','penalty'].map(k=>'<td>'+v[k]+'</td>').join('')+'</tr>').join('')+'</table></div></details>'+
 '<details><summary>Recorded events · edit / correct</summary>'+events.map(ev=>'<p>'+e(ev.side)+' · '+e(ev.type)+' · '+(ev.playerId?e(label(ev.playerId)):'Unknown')+(ev.primaryAssist?' · A1 '+e(label(ev.primaryAssist)):'')+(ev.secondaryAssist?' · A2 '+e(label(ev.secondaryAssist)):'')+' · P'+ev.period+' <button onclick="editStat(&#39;'+e(ev.id)+'&#39;)">Edit</button> <button onclick="deleteStat(&#39;'+e(ev.id)+'&#39;)">Delete</button></p>').join('')+'</details>'+
 '<p class="muted">A goal counts as a shot. Record shots and saves separately only when appropriate.</p>'+(events.length?'<button onclick="undoStat()">Undo last</button>':'');
}

function nextPreviewRecord(){let r=lineupRecord();if(!r.preview)r.preview={mode:s.mode[s.game]==='fixed'?'fixed':'dynamic',index:0,edits:{}};return r.preview}
function nextLineOptions(){let gm=s.games[s.game],r=lineupRecord(),p=nextPreviewRecord(),eligible=gamePresent(s.game).filter(id=>id!==gm.goalie),n=gameSkaters(s.game),planned=gm.shifts||[],current=r.current||[];
 if(p.mode==='fixed'){let options=planned.slice(Math.min(s.shift+1,planned.length)).concat(planned.slice(0,Math.min(s.shift+1,planned.length))).map(ids=>ids.filter(id=>eligible.includes(id)).slice(0,n));return (options.length?options:[eligible.slice(0,n)]).map(ids=>ids.concat(eligible.filter(id=>!ids.includes(id)).slice(0,n-ids.length)))}
 let totals=lineupTotals(),base=[...eligible].sort((a,b)=>(totals[a]||0)-(totals[b]||0)||a-b),options=[];
 for(let offset=0;offset<Math.max(1,eligible.length);offset++){let order=base.slice(offset).concat(base.slice(0,offset)),ids=order.slice(0,n);if(ids.length===n&&!options.some(x=>x.join(',')===ids.join(',')))options.push(ids)}
 return options.length?options:[base.slice(0,n)]
}
function nextPreviewLine(){let p=nextPreviewRecord(),opts=nextLineOptions();p.index=((p.index%opts.length)+opts.length)%opts.length;let key=p.mode+':'+p.index,edited=p.edits[key],eligible=gamePresent(s.game).filter(id=>id!==s.games[s.game].goalie),n=gameSkaters(s.game);return Array.isArray(edited)&&edited.length===n&&new Set(edited).size===n&&edited.every(id=>eligible.includes(id))?edited:opts[p.index]}
function browseNextLine(direction){let p=nextPreviewRecord(),options=nextLineOptions();p.index=(p.index+direction+options.length)%options.length;save();render()}
function setNextMode(mode){if(!['fixed','dynamic'].includes(mode))return;let p=nextPreviewRecord();p.mode=mode;p.index=0;save();render()}
function editNextPlayer(slot,value){let id=Number(value),p=nextPreviewRecord(),ids=nextPreviewLine().slice(),eligible=gamePresent(s.game).filter(x=>x!==s.games[s.game].goalie);if(!eligible.includes(id)||ids.some((x,i)=>i!==slot&&x===id))return alert('Choose a different available skater.');ids[slot]=id;p.edits[p.mode+':'+p.index]=ids;save();render()}
function confirmNextLineup(){let ids=nextPreviewLine().slice();if(ids.length!==gameSkaters(s.game))return alert('Not enough eligible skaters for this lineup.');confirmLineup(ids,'preview');let p=nextPreviewRecord();p.index=0;p.edits={};save()}
function lineupPanel(){let r=lineupRecord(),gm=s.games[s.game],p=nextPreviewRecord(),options=nextLineOptions(),next=nextPreviewLine(),eligible=gamePresent(s.game).filter(id=>id!==gm.goalie);
 return '<h3>Current line · '+(r.current?'confirmed':'not started')+'</h3>'+(r.current?r.current.map(id=>'<span class="pill">'+e(label(id))+'</span>').join(''):'<p class="muted">No active lineup confirmed yet.</p>')+'<p>Goalie: '+e(label(gm.goalie))+'</p>'+(r.pending?'<p><strong>Shift due — confirm when players change.</strong></p>':'')+
 '<div class="card"><h3>Next line · preview only</h3><label>Rotation <select onchange="setNextMode(this.value)"><option value="fixed" '+(p.mode==='fixed'?'selected':'')+'>Fixed lines</option><option value="dynamic" '+(p.mode==='dynamic'?'selected':'')+'>Dynamic rotation</option></select></label><p class="muted">Option '+(p.index+1)+' of '+options.length+' · tap a skater to replace</p><div class="row">'+next.map((id,i)=>'<label>'+e('Position '+(i+1))+' <select aria-label="Next line skater '+(i+1)+'" onchange="editNextPlayer('+i+',this.value)">'+eligible.map(x=>'<option value="'+x+'" '+(id===x?'selected':'')+'>'+e(label(x))+'</option>').join('')+'</select></label>').join('')+'</div><div class="row"><button onclick="browseNextLine(-1)">← Previous</button><button onclick="browseNextLine(1)">Next →</button><button class="primary" onclick="confirmNextLineup()">Confirm shift change</button></div><p class="muted">Browsing or editing does not affect the current line or ice time.</p></div>'+
 '<div class="row"><button onclick="substitutePlayers()">Substitute current players</button>'+(r.pending?'<button onclick="keepCurrentLineup()">Keep current / extend</button>':'')+'</div>'+substitutionPanel()+(benchConfig().ice?'<h3>Estimated on-ice duration</h3>'+Object.entries(lineupTotals()).map(([id,sec])=>'<span class="pill">'+e(label(+id))+': '+Math.floor(sec/60)+'m '+Math.floor(sec%60)+'s</span>').join('')+'<p class="muted">Based on confirmed lineups; includes clock stoppages.</p>':'')
}
function liveView(){if(!s.games.length)return '<section class="card">Generate rotations first.</section>';let gm=s.games[s.game],c=gameClock(),cfg=benchConfig();return '<section class="card"><h2>Live bench · '+e(gameOpponentLabel(s.game))+'</h2><p class="muted">'+gameSkaters(s.game)+' skaters · '+gamePresent(s.game).length+' available including goalie</p>'+gameFormatPanel(s.game)+(gameScheduleMeta(s.game)?'<p class="muted">'+e(gameScheduleMeta(s.game))+'</p>':'')+'<div class="row"><label>Game <select onchange="stop();s.game=+this.value;s.shift=0;s.seconds=shiftSeconds();save();render()">'+s.games.map((_,i)=>'<option value="'+i+'" '+(s.game===i?'selected':'')+'>'+e(gameOpponentLabel(i))+'</option>').join('')+'</select></label></div><div class="muted">Period '+c.period+' · game clock</div>'+(cfg.gameClock?'<div class="clock" id="game-clock">'+clockText(c)+'</div>':'')+'<div class="row">'+(c.ended?(c.period<s.settings.periodCount?'<button class="primary" onclick="clockNext()">Next period</button>':'<strong>Game complete</strong>'):'<button class="primary" onclick="clockToggle()">'+(c.since?'Pause':'Start')+' clock</button><button onclick="clockEnd()">End period</button>')+'</div>'+(cfg.mode==='timed'?'<h3>Timed shifts</h3>'+(cfg.shiftClock?'<div class="clock" id="clock">'+fmt(s.seconds)+'</div>':'')+'<div class="row"><button class="primary" onclick="toggle()">'+(timer?'Pause':'Start')+' shift</button><button onclick="nextPlannedLine()">Next shift →</button></div>':cfg.mode==='manual'?'<h3>Manual line '+(s.shift+1)+'/'+gm.shifts.length+'</h3><button class="primary" onclick="nextPlannedLine()">Next line →</button>':'')+(cfg.mode!=='off'?lineupPanel():'')+(cfg.stats?statsPanel():'')+(cfg.ice?'':'')+'</section>'}

function practiceCount(id){return s.practiceSessions.filter(x=>x.playerId===id).length}
function practiceEligible(){let allowed=s.settings.practiceEligible;return s.players.filter(x=>allowed===null||allowed.includes(x.id))}
function practiceRank(){let eligible=practiceEligible();if(s.settings.practiceMode==='roundRobin'){let last=s.practiceSessions.length?s.practiceSessions[s.practiceSessions.length-1].playerId:null;let i=eligible.findIndex(x=>x.id===last);return eligible.slice(i+1).concat(eligible.slice(0,i+1))}return eligible.slice().sort((a,b)=>practiceCount(a.id)-practiceCount(b.id)||a.id-b.id)}
function practiceView(){let ranked=practiceRank(),suggested=s.settings.practiceMode==='manual'?[]:ranked.slice(0,s.settings.practicePerSession);return '<section class="card"><h2>Goalie practice rotation</h2><p class="muted">Rotation: '+e(s.settings.practiceMode)+' · '+s.settings.practicePerSession+' goalie trainee(s) per session. Change rules in Settings.</p><p><strong>Suggested next:</strong> '+(suggested.map(x=>e(label(x.id))).join(', ')||'Choose eligible players in Settings')+'</p><div class="row"><label>Date <input id="practiceDate" type="date" value="'+new Date().toLocaleDateString('en-CA')+'"></label></div><div id="practiceChoices">'+Array.from({length:s.settings.practicePerSession},(_,i)=>'<div class="row"><label>Trainee '+(i+1)+' <select class="practicePlayer"><option value="">Choose player</option>'+ranked.map(x=>'<option value="'+x.id+'" '+(suggested[i]?.id===x.id?'selected':'')+'>'+e(label(x.id))+' ('+practiceCount(x.id)+' sessions)</option>').join('')+'</select></label></div>').join('')+'</div><button class="primary" onclick="addPractice()">Record practice goalies</button><h3>Training totals</h3>'+s.players.map(x=>'<span class="pill">'+e(label(x.id))+': '+practiceCount(x.id)+'</span>').join('')+'<h3>Practice history</h3>'+(s.practiceSessions.length?'<div class="scroll"><table><tr><th>Date</th><th>Player</th><th></th></tr>'+s.practiceSessions.map((x,i)=>({x,i})).reverse().map(({x,i})=>'<tr><td>'+e(x.date)+'</td><td>'+e(label(x.playerId))+'</td><td><button onclick="removePractice('+i+')">Delete</button></td></tr>').join('')+'</table></div>':'<p>No practice sessions recorded yet.</p>')+'</section>'}
function addPractice(){let date=document.getElementById('practiceDate').value,ids=[...document.querySelectorAll('.practicePlayer')].map(x=>+x.value).filter(Boolean);if(!date||!ids.length||new Set(ids).size!==ids.length||ids.some(id=>!practiceEligible().some(p=>p.id===id)))return alert('Choose a date and unique eligible players');ids.forEach(playerId=>s.practiceSessions.push({date,playerId}));save();render()}
function removePractice(i){if(!confirm('Delete this practice assignment?'))return;s.practiceSessions.splice(i,1);save();render()}
const DIVISION_PRESETS={'6U':{gameCount:3,gameMinutes:12,shiftMinutes:2,skaters:4},'8U':{gameCount:3,gameMinutes:16,shiftMinutes:2,skaters:5},'10U':{gameCount:1,gameMinutes:36,shiftMinutes:2,skaters:5},'12U':{gameCount:1,gameMinutes:45,shiftMinutes:2,skaters:5},'14U':{gameCount:1,gameMinutes:45,shiftMinutes:2,skaters:5},'16U':{gameCount:1,gameMinutes:51,shiftMinutes:2,skaters:5},'18U':{gameCount:1,gameMinutes:51,shiftMinutes:2,skaters:5}};
function selectDivision(div){if(div==='Custom'){s.settings.division='Custom';save();render();return}if(!DIVISION_PRESETS[div])return;if(!confirm('Apply example '+div+' game settings? Your roster, history and goalie practice records will be preserved. Existing generated rotations will remain until you regenerate them.'))return;Object.assign(s.settings,DIVISION_PRESETS[div],{division:div,benchMode:null,benchStats:null,benchIce:null,benchGameClock:true,benchShiftClock:true});s.mode=gameIndexes().map(i=>s.mode[i]||'mixed');s.goalies=gameIndexes().map(i=>s.goalies[i]??null);s.seconds=shiftSeconds();save();render()}
function updateSetting(key,value){if(['gameCount','gameMinutes','periodCount','periodMinutes','shiftMinutes','skaters','practicePerSession'].includes(key))value=Number(value);s.settings[key]=value;if(['gameCount','gameMinutes','periodCount','periodMinutes','shiftMinutes','skaters'].includes(key))s.settings.division='Custom';s=migrateData(s);s.mode=gameIndexes().map(i=>s.mode[i]||'mixed');s.goalies=gameIndexes().map(i=>s.goalies[i]??null);save();render()}
function toggleGameEligible(id,checked){let all=s.players.map(x=>x.id),current=s.settings.gameGoalieEligible===null?all.slice():s.settings.gameGoalieEligible.slice();s.settings.gameGoalieEligible=checked?[...new Set([...current,id])]:current.filter(x=>x!==id);save();render()}
function togglePracticeEligible(id,checked){let all=s.players.map(x=>x.id),current=s.settings.practiceEligible===null?all.slice():s.settings.practiceEligible.slice();s.settings.practiceEligible=checked?[...new Set([...current,id])]:current.filter(x=>x!==id);save();render()}
function settingsView(){let z=s.settings;return window.HockeyCloud.panel()+'<section class="card"><h2>App settings</h2><div class="row"><label>Age division <select onchange="selectDivision(this.value)">'+['6U','8U','10U','12U','14U','16U','18U','Custom'].map(d=>'<option value="'+d+'" '+(z.division===d?'selected':'')+'>'+d+'</option>').join('')+'</select></label></div><p class="muted">Division presets are editable examples, not official association rules. Changing divisions does not erase your roster or history.</p><div class="row"><label>App title <input aria-label="App title" value="'+e(window.HockeyCloud.team?.name||z.title)+'" '+(window.HockeyCloud.team?'disabled title="Team name is managed by the workspace"':'')+' onchange="updateSetting(\'title\',this.value.trim()||\'Hockey Coach\')"></label></div>' +(window.HockeyCloud.team?'':'<div class="row"><label>Heading color <input type="color" value="'+e(z.headingColor)+'" onchange="updateSetting(\'headingColor\',this.value)"></label></div>')+ ''+benchSettings()+'<h3>Games and shifts</h3>'+[['gameCount','Games per day',1,12,1],['gameMinutes','Minutes per game',1,120,1],['shiftMinutes','Minutes per shift',0.5,30,0.5],['skaters','Skaters on ice',1,10,1]].map(([key,name,min,max,step])=>'<div class="row"><label>'+name+' <input type="number" min="'+min+'" max="'+max+'" step="'+step+'" value="'+z[key]+'" onchange="updateSetting(\''+key+'\',this.value)"></label></div>').join('')+'<h3>Period configuration</h3><div class="row"><label>Periods per game <input type="number" min="1" max="6" value="'+z.periodCount+'" onchange="updateSetting(&quot;periodCount&quot;,this.value)"></label><label>Minutes per period <input type="number" min="1" max="120" value="'+periodMinutes()+'" onchange="updateSetting(&quot;periodMinutes&quot;,this.value)"></label></div><p class="muted">Existing teams default to one period using the previous game length.</p><h3>Game goalie rotation</h3><label>Automatic assignments <select onchange="updateSetting(\'gameGoalieMode\',this.value)"><option value="unique" '+(z.gameGoalieMode==='unique'?'selected':'')+'>Different goalie each game when possible</option><option value="dedicated" '+(z.gameGoalieMode==='dedicated'?'selected':'')+'>Dedicated goalie pool</option><option value="balanced" '+(z.gameGoalieMode==='balanced'?'selected':'')+'>Fewest previous games (repeats allowed)</option></select></label><p class="muted">You can override any game goalie manually on the Game day tab. Dedicated goalie eligibility:</p>'+s.players.map(x=>'<label class="pill"><input type="checkbox" '+(z.gameGoalieEligible===null||z.gameGoalieEligible.includes(x.id)?'checked':'')+' onchange="toggleGameEligible('+x.id+',this.checked)"> '+e(label(x.id))+'</label>').join('')+'<h3>Goalie practice rotation</h3><div class="row"><label>Rotation method <select onchange="updateSetting(\'practiceMode\',this.value)"><option value="least" '+(z.practiceMode==='least'?'selected':'')+'>Fewest practices first</option><option value="roundRobin" '+(z.practiceMode==='roundRobin'?'selected':'')+'>Roster order / round robin</option><option value="manual" '+(z.practiceMode==='manual'?'selected':'')+'>Manual choice</option></select></label><label>Trainees per practice <input type="number" min="1" max="5" value="'+z.practicePerSession+'" onchange="updateSetting(\'practicePerSession\',this.value)"></label></div><p>Eligible players (all included by default):</p>'+s.players.map(x=>'<label class="pill"><input type="checkbox" '+(z.practiceEligible===null||z.practiceEligible.includes(x.id)?'checked':'')+' onchange="togglePracticeEligible('+x.id+',this.checked)"> '+e(label(x.id))+'</label>').join('')+'<p class="muted">Changes to game settings apply to newly generated rotations. Existing history is retained. Export a backup from History before major changes.</p><h3>Support and updates</h3><div class="row"><button onclick="sendFeedback()">Send feedback</button><button onclick="showWhatsNew(false)">What\'s New</button></div><p class="muted">Hockey Coach · Version '+APP_VERSION+'</p></section>'}
function sendFeedback(){location.href='mailto:twilson9034@gmail.com?subject='+encodeURIComponent('Hockey Coach v'+APP_VERSION+' feedback')+'&body='+encodeURIComponent('App version: '+APP_VERSION+'\n\nFeedback:\n')}
function infoView(){return '<section class="card"><h2>About Hockey Coach</h2><p>Manage youth hockey rosters, attendance, shifts, game goalies and goalie practice rotations.</p><h3>How to use</h3><p>Choose age division and game rules in Settings, mark attendance in Roster, generate lineups on Game day, and use Live bench for shift timing.</p><h3>Your data</h3><p>Records are stored on this device and do not automatically sync between coaches. Export a backup from History before clearing website data or changing devices.</p><h3>Install</h3><p>On iPhone, open in Safari and choose Share → Add to Home Screen. On Android, use your browser menu to install or add to home screen.</p><p class="muted">Version '+APP_VERSION+'</p></section>'}
