function statReportGames(){
 const archived=s.history.flatMap((h,hi)=>(h.games||[]).map((g,i)=>{
  const schedule=h.schedule||{},date=schedule.start?new Date(Date.parse(schedule.start)+i*(Number(schedule.interval)||20)*60000):null;
  return {key:'archive-'+hi+'-'+i,day:h.day,game:i,opponent:schedule.opponents?.[i]||'Opponent not recorded',date:date&&Number.isFinite(+date)?date.toISOString().slice(0,10):'',events:h.stats?.[h.day+'-'+i]||[],goalie:g.goalie,archived:true};
 }));
 const schedule=s.daySchedule||activeGameSchedule()||{};
 const current=s.games.map((g,i)=>{const date=schedule.start?new Date(Date.parse(schedule.start)+i*(Number(schedule.interval)||20)*60000):null;return {key:'current-'+i,day:s.day,game:i,opponent:schedule.opponents?.[i]||'Opponent not recorded',date:date&&Number.isFinite(+date)?date.toISOString().slice(0,10):'',events:s.statEvents?.[s.day+'-'+i]||[],goalie:g.goalie,archived:false}});
 return [...archived,...current];
}
function statFilteredGames(){
 let games=statReportGames();
 if(statsView==='game')return games.filter(g=>g.key===statsGame).length?games.filter(g=>g.key===statsGame):games.slice(-1);
 return games.filter(g=>(!statsFrom||g.date&&g.date>=statsFrom)&&(!statsTo||g.date&&g.date<=statsTo)&&(!statsOpponent||g.opponent===statsOpponent));
}
function statReport(){
 const games=statFilteredGames(),events=games.flatMap(g=>g.events),team=(side,type)=>events.filter(v=>v.side===side&&(v.type===type||(type==='shot'&&v.type==='goal'))).length;
 const players=statsSummary(events);
 const gp={};for(const g of games){const ids=new Set();for(const ev of g.events){if(ev.side!=='us')continue;for(const id of [ev.playerId,ev.primaryAssist,ev.secondaryAssist])if(id!=null)ids.add(id)}for(const id of ids)gp[id]=(gp[id]||0)+1}
 const goalie={};for(const g of games){if(g.goalie==null)continue;const row=goalie[g.goalie]||(goalie[g.goalie]={games:0,saves:0,against:0});row.games++;row.saves+=g.events.filter(x=>x.side==='us'&&x.type==='save'&&(x.playerId==null||x.playerId===g.goalie)).length;row.against+=g.events.filter(x=>x.side==='them'&&x.type==='goal').length}
 const rows=Object.entries(players).map(([id,v])=>({id:+id,GP:gp[id]||0,G:v.goal,A:v.assist,PTS:v.goal+v.assist,SOG:v.shot,Saves:v.save,Penalties:v.penalty})).sort((a,b)=>b.PTS-a.PTS||b.G-a.G);
 return {games,events,rows,goalie,team:{goals:team('us','goal'),opponentGoals:team('them','goal'),shots:team('us','shot'),opponentShots:team('them','shot'),saves:team('us','save'),opponentSaves:team('them','save')}};
}
function selectedStatPlayer(){const ids=s.players.map(x=>String(x.id));if(!ids.includes(String(statsPlayer)))statsPlayer=ids[0]||'';return statsPlayer}
function selectStatPlayer(id){statsPlayer=String(id);statsScope='individual';render()}
function statScopedReport(report){if(statsScope!=='individual')return report;const id=selectedStatPlayer();return {...report,rows:report.rows.filter(row=>String(row.id)===id),goalie:Object.fromEntries(Object.entries(report.goalie).filter(([key])=>key===id))}}
function statPlayerBreakdown(report){if(statsScope!=='individual')return '';const id=selectedStatPlayer();const games=report.games.map(g=>{const counts=statsSummary(g.events)[id]||{goal:0,assist:0,shot:0,save:0,penalty:0};return {game:g,counts}});return '<h3>Game-by-game performance</h3><div class="scroll"><table><tr><th>Date / Opponent</th><th>G</th><th>A</th><th>PTS</th><th>SOG</th><th>Saves</th><th>Penalties</th></tr>'+games.map(({game:g,counts:c})=>'<tr><td>'+e((g.date||'Undated')+' · '+g.opponent)+'</td>'+[c.goal,c.assist,c.goal+c.assist,c.shot,c.save,c.penalty].map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</table></div>'}
function statDisplayName(id){const player=p(id);return statsNames?(player?.name||'Unknown player'):'#'+(player?.number||'?')}
function statReportTitle(report){return (statsScope==='individual'?((statsNames?p(+selectedStatPlayer())?.name:'#'+(p(+selectedStatPlayer())?.number||'?'))||'Player')+' · ':'')+(statsView==='game'?(report.games[0]?'Game vs '+report.games[0].opponent+' · '+(report.games[0].date||'Date unavailable'):'Game statistics'):'Season to date'+(statsFrom||statsTo?' · '+(statsFrom||'Start')+' to '+(statsTo||'Today'):'')+(statsOpponent?' · '+statsOpponent:''))}
function statReportTable(report){
 return '<div class="scroll"><table><thead><tr><th>Player</th><th>GP*</th><th>G</th><th>A</th><th>PTS</th><th>SOG</th><th>Saves</th><th>Penalties</th></tr></thead><tbody>'+report.rows.map(v=>'<tr><td>'+(statsScope==='all'?'<button type="button" onclick="selectStatPlayer('+JSON.stringify(v.id)+')">'+e(statDisplayName(v.id))+'</button>':e(statDisplayName(v.id)))+'</td>'+['GP','G','A','PTS','SOG','Saves','Penalties'].map(k=>'<td>'+v[k]+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="muted">*GP is games with a recorded player event; it is not an attendance total. Penalties are event counts, not minutes.</p>';
}
function statGoalieTable(report){
 const rows=Object.entries(report.goalie);
 return rows.length?'<h3>Goalies</h3><div class="scroll"><table><tr><th>Goalie</th><th>Games</th><th>Saves</th><th>GA</th><th>Save %</th></tr>'+rows.map(([id,v])=>'<tr><td>'+e(statDisplayName(+id))+'</td><td>'+v.games+'</td><td>'+v.saves+'</td><td>'+v.against+'</td><td>—</td></tr>').join('')+'</table></div><p class="muted">Save % withheld because shot and save event completeness cannot be verified.</p>':'';
}
function statisticsView(){
 const all=statReportGames(),report=statScopedReport(statReport()),opts=[...new Set(all.map(g=>g.opponent))].sort();
 return '<section class="card"><h2>Statistics</h2><div class="row"><button class="'+(statsScope==='all'?'primary':'')+'" onclick="statsScope=&#39;all&#39;;render()">All Players</button><button class="'+(statsScope==='individual'?'primary':'')+'" onclick="statsScope=&#39;individual&#39;;render()">Individual Player</button></div>'+(statsScope==='individual'?'<label>Player <select onchange="statsPlayer=this.value;render()">'+s.players.map(x=>'<option value="'+e(x.id)+'" '+(String(x.id)===selectedStatPlayer()?'selected':'')+'>'+e('#'+x.number+' '+x.name)+'</option>').join('')+'</select></label>':'')+'<div class="row"><button class="'+(statsView==='game'?'primary':'')+'" onclick="statsView=&#39;game&#39;;render()">Game Stats</button><button class="'+(statsView==='season'?'primary':'')+'" onclick="statsView=&#39;season&#39;;render()">Season to Date</button></div>'+
 (statsView==='game'?'<label>Game <select onchange="statsGame=this.value;render()">'+all.map(g=>'<option value="'+e(g.key)+'" '+(report.games[0]?.key===g.key?'selected':'')+'>'+e((g.date||'Undated')+' · '+g.opponent+' · Day '+g.day+' / Game '+(g.game+1))+'</option>').join('')+'</select></label>':'<div class="row"><label>From <input type="date" value="'+e(statsFrom)+'" onchange="statsFrom=this.value;render()"></label><label>To <input type="date" value="'+e(statsTo)+'" onchange="statsTo=this.value;render()"></label><label>Opponent <select onchange="statsOpponent=this.value;render()"><option value="">All opponents</option>'+opts.map(x=>'<option value="'+e(x)+'" '+(statsOpponent===x?'selected':'')+'>'+e(x)+'</option>').join('')+'</select></label></div>')+
 '<h3>'+e(statReportTitle(report))+'</h3><p>'+report.games.length+' game(s) · <strong>'+report.team.goals+'–'+report.team.opponentGoals+' goals</strong> · Shots '+report.team.shots+'–'+report.team.opponentShots+' · Saves '+report.team.saves+'</p>'+
 statReportTable(report)+statGoalieTable(report)+statPlayerBreakdown(report)+
 '<label><input type="checkbox" '+(statsNames?'checked':'')+' onchange="statsNames=this.checked;render()"> Include player names in exports and reports (otherwise jersey numbers)</label>'+
 '<div class="row"><button onclick="exportStatisticsCSV(false)">Export CSV</button><button onclick="printStatistics()">Print / Save PDF</button><button class="primary" onclick="shareStatistics()">Share / Send</button></div><p class="muted">On iPhone, Print → pinch open the preview → Share → Save to Files creates a PDF. Sharing uses the device share sheet where supported.</p></section>';
}
function statisticsCSV(){
 const r=statScopedReport(statReport()),lines=[['Team',window.HockeyCloud?.team?.name||s.settings.title],['Report',statReportTitle(r)],['Generated',new Date().toISOString()],['Games',r.games.length],['Goals for',r.team.goals],['Goals against',r.team.opponentGoals],['Shots for',r.team.shots],['Shots against',r.team.opponentShots],[],['Player','GP (recorded events)','Goals','Assists','Points','Shots','Saves','Penalty events'],...r.rows.map(x=>[statDisplayName(x.id),x.GP,x.G,x.A,x.PTS,x.SOG,x.Saves,x.Penalties]),[],['Goalie','Games','Saves','Goals against','Save percentage'],...Object.entries(r.goalie).map(([id,x])=>[statDisplayName(+id),x.games,x.saves,x.against,'Not verified']),...(statsScope==='individual'?[[],['Game date','Opponent','Goals','Assists','Points','Shots','Saves','Penalty events'],...r.games.map(g=>{const c=statsSummary(g.events)[selectedStatPlayer()]||{goal:0,assist:0,shot:0,save:0,penalty:0};return [g.date,g.opponent,c.goal,c.assist,c.goal+c.assist,c.shot,c.save,c.penalty]})]:[])];
 return lines.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
}
function statFilename(ext){return 'hockey-stats-'+(statsView==='game'?'game':'season')+'-'+(statsScope==='individual'?'player-'+selectedStatPlayer():'all-players')+'-'+new Date().toISOString().slice(0,10)+'.'+ext}
function statDownload(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportStatisticsCSV(){statDownload(new Blob(['\uFEFF'+statisticsCSV()],{type:'text/csv;charset=utf-8'}),statFilename('csv'))}
async function shareStatistics(){
 const file=new File(['\uFEFF'+statisticsCSV()],statFilename('csv'),{type:'text/csv'});
 try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:statReportTitle(statReport())});return}
 if(navigator.share){await navigator.share({title:statReportTitle(statReport()),text:statisticsCSV()});return}
 exportStatisticsCSV();alert('CSV downloaded. You can attach it to a message or email.');
 }catch(err){if(err?.name!=='AbortError')alert('Sharing was unavailable. Use Export CSV or Print / Save PDF.')}
}
function printStatistics(){
 const r=statScopedReport(statReport()),win=window.open('','_blank');if(!win)return alert('Allow pop-ups to print this report.');
 const html='<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(statReportTitle(r))+'</title><style>body{font:14px system-ui;padding:24px;color:#111}.report-toolbar{position:sticky;top:0;background:#fff;padding:12px 0;display:flex;gap:10px;flex-wrap:wrap;border-bottom:1px solid #ddd;margin-bottom:20px}.report-toolbar button,.report-toolbar a{font:inherit;padding:10px 14px;border:1px solid #888;border-radius:8px;color:#111;background:#f5f5f5;text-decoration:none;cursor:pointer}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:7px;border-bottom:1px solid #ccc;text-align:left}.scroll{overflow:visible}.muted{color:#555}@media print{body{padding:0}.report-toolbar{display:none!important}}</style></head><body><nav class="report-toolbar"><button type="button" onclick="window.close()">Close report ✕</button><a href="'+e(location.href)+'">Back to Hockey Coach</a><button type="button" onclick="window.print()">Print / Save PDF</button></nav><h1>'+e(window.HockeyCloud?.team?.name||s.settings.title)+'</h1><h2>'+e(statReportTitle(r))+'</h2><p>Generated '+e(new Date().toLocaleString())+' · '+r.games.length+' games · Goals '+r.team.goals+'–'+r.team.opponentGoals+' · Shots '+r.team.shots+'–'+r.team.opponentShots+'</p>'+statReportTable(r)+statGoalieTable(r)+statPlayerBreakdown(r)+'</body></html>';
 win.document.open();win.document.write(html);win.document.close();win.focus();setTimeout(()=>win.print(),300);
}

function historyView(){const career=statsSummary([...s.history.flatMap(h=>Object.values(h.stats||{}).flat()),...Object.values(s.statEvents||{}).flat()]);return '<section class="card"><h2>Player statistics · all recorded games</h2><div class="scroll"><table><tr><th>Player</th><th>G</th><th>A</th><th>Shots</th><th>Saves</th><th>Penalties</th></tr>'+Object.entries(career).map(([id,v])=>'<tr><td>'+e(label(+id))+'</td>'+['goal','assist','shot','save','penalty'].map(k=>'<td>'+v[k]+'</td>').join('')+'</tr>').join('')+'</table></div></section><section class="card"><h2>Previous game days</h2>'+(s.history.map(h=>'<p>Day '+h.day+': '+h.goalies.map(id=>e(label(id))).join(' / ')+'</p>').join('')||'<p>No completed days yet.</p>')+'</section><section class="card"><h2>Backup</h2><div class="row"><button onclick="backup()">Export JSON</button><label>Import <input type="file" accept=".json,application/json" onchange="restore(this.files[0])"></label></div><p class="muted">Data is stored only on this device. Export backups regularly; clearing website data may delete it.</p></section>'}function fmt(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}function stop(){if(timer){clearInterval(timer);timer=null}}function toggle(){if(timer){stop();render();return}let end=Date.now()+s.seconds*1000;timer=setInterval(()=>{s.seconds=Math.max(0,Math.ceil((end-Date.now())/1000));save();let el=document.getElementById('clock');if(el)el.textContent=fmt(s.seconds);if(s.seconds===0){stop();lineupRecord().pending=true;save();render()}},250);render()}function advance(){stop();if(s.shift<s.games[s.game].shifts.length-1)s.shift++;else if(s.game<s.games.length-1){s.game++;s.shift=0}else return alert('All games complete');s.seconds=shiftSeconds();save();render()}function backup(){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));a.href=url;a.download='hockey-backup-day-'+s.day+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}async function restore(f){if(!f)return;try{let d=JSON.parse(await f.text());if(!Array.isArray(d.players)||!Array.isArray(d.history))throw Error('Invalid backup');if(confirm('Replace existing data?')){s=migrateData(d);save();render()}}catch(err){alert(err.message)}}window.hockeyCloudSetData=function(data,teamId){stop();if(!teamId){let raw=localStorage.getItem(KEY);s=migrateData(raw?JSON.parse(raw):fresh())}else{s=migrateData(data||fresh())}s.mode=gameIndexes().map(i=>s.mode[i]||'mixed');s.goalies=gameIndexes().map(i=>s.goalies[i]??null);render()};render();setInterval(()=>{if(tab==='live'){let el=document.getElementById('game-clock');if(el)el.textContent=clockText(gameClock())}},500);window.HockeyCloud.init().finally(()=>window.hockeyStartupReveal?.());if('serviceWorker'in navigator)void 0;